const BASE_FORMAT = "%s [%c%s%c] [%c%s%c] ";
const LEVEL_NAMES = [
  "",
  // OFF
  "ERR",
  "WRN",
  "INF",
  "DBG",
  "VRB"
];
const COLORS = [
  "",
  // OFF
  "color: #7a5f9d",
  "color: #8d7041",
  "color: #396c9e",
  "color: #437761",
  "color: #7a5f9d"
];
const TAG_COLORS = [
  "color: #437761",
  "color: #537a36",
  "color: #8d7041",
  "color: #396c9e",
  "color: #7a5f9d",
  "color: #7a5f9d"
];
const defaultLoggingHandler = (color, level, tag, fmt, args) => {
  console.log(
    BASE_FORMAT + fmt,
    (/* @__PURE__ */ new Date()).toISOString(),
    COLORS[level],
    LEVEL_NAMES[level],
    "",
    TAG_COLORS[color],
    tag,
    "",
    ...args
  );
};
export {
  defaultLoggingHandler
};
